"""Authoring tool: regenerate chapter data AND intentionally re-pin citations after review."""
import pathlib,json,hashlib,re
R=pathlib.Path(__file__).resolve().parents[1]; files={f['path']:f for f in json.loads((R/'content/snapshot.json').read_text())}; pages=[]
def ref(path,needle=None,count=16):
 lines=files[path]['text'].split('\n');
 if needle and not any(needle in l for l in lines): raise ValueError(path+' missing anchor: '+needle)
 start=next((i for i,l in enumerate(lines) if needle and needle in l),0); end=min(len(lines),start+count)
 return {'path':path,'start':start+1,'end':end,'hash':hashlib.sha256('\n'.join(lines[start:end]).encode()).hexdigest()}
def sec(title,body,path,needle=None,items=None,table=None,diagram=None):
 d={'title':title,'paragraphs':body.split('\n\n'),'refs':[ref(path,needle)]}
 if items:d['items']=items
 if table:d['table']=table
 if diagram:d['diagram']={'code':diagram,'caption':title+' — relationships shown are supported by the linked source; this is a conceptual view, not a deployment trace.'}
 return d
def page(slug,title,desc,angle,sections,kind='chapter'):
 pages.append({'slug':slug,'title':title,'description':desc,'interview':angle,'sections':sections,'kind':kind})
page('start-here','Start Here','A source-grounded guide to Mailloop, from first sign-in to the delivery boundary.', 'Explain the product in one sentence, then name the hardest consistency boundary: a database transaction cannot include Gmail accepting a message.',[
 sec('The 30-second pitch','Mailloop helps job seekers send personalized cold emails through their own Gmail account. A template and selected contacts become a campaign, with one separate message per recipient. The app adds contact management, PDF attachments, usage controls and Premium billing.\n\nThis handbook documents a dated source snapshot. It does not establish observed production behavior, Google verification, customer outcomes, or interview mastery. Start with Architecture, trace Sending, then use Walkthroughs to rehearse an explanation.', 'AGENTS.md', 'Mailloop is'),
 sec('The two-minute pitch','A signed-in user prepares contacts and a template in a Next.js interface. Server actions validate ownership, effective access and capacity, then atomically create campaign snapshots and usage reservations in PostgreSQL. After commit, the dispatcher publishes individual send events to Inngest.\n\nThe worker prepares Gmail credentials and MIME outside database locks, then checks fresh controls and claims one delivery. Acceptance confirms usage. An ambiguous submission becomes UNCERTAIN, retains accounting and blocks automatic resend. Dodo webhooks and scheduled provider reconciliation maintain subscription observations; entitlements decide what the user can do now.', 'src/lib/campaigns.ts', 'export async function createCampaign',diagram='flowchart LR\n A[Contacts and template] --> B[Campaign plus reservations]\n B --> C[Inngest event]\n C --> D[Gmail send]\n D --> E[Confirmed or uncertain]'),
 sec('Read the current limits','With paid gating enabled, Free allows 3 recipients per campaign, 3 emails per UTC day and 15 per month. Premium allows 10 recipients per campaign, 20 per UTC day and 300 per allowance period. PAID is the internal enum; Premium is the public label.\n\nA 15-recipient request fails campaignSchema, whose array maximum is 10. A Free request containing 4 valid recipients passes that schema but fails the plan-specific campaign check. Do not describe a 15-message batch as current behavior.', 'src/lib/plans.ts','export const PLANS',table=[['Limit','Free','Premium'],['Recipients / campaign','3','10'],['Emails / UTC day','3','20'],['Emails / allowance','15','300'],['Saved templates with gating','1','Unlimited']]),
 sec('A deliberate reading path','Learn the nouns first: User, Campaign, Send and UsageReservation. Then trace one successful delivery, one uncertain delivery and one paid upgrade. Finish by explaining what evidence cannot tell you. The source browser preserves source line positions, including visible redactions. Every excerpt is checked against an expected hash.', 'src/lib/validation.ts','export const campaignSchema',items=['New to the code: Start Here → Architecture → Database → Authentication.','Working on sending: Sending → Inngest → Security/Reliability → Walkthroughs.','Interview revision: Tradeoffs → Interview Prep → Cheat Sheet.','Use the Function/API Reference and source browser to check details rather than memorizing file names.'])])
page('architecture','Architecture','A modular Next.js application with durable database state and external providers.', 'Describe each boundary and identify which component owns durable truth. Avoid claiming a particular hosting topology is already deployed.',[
 sec('Runtime boundaries','The application uses the App Router, server components, interactive client components, server actions and route handlers. Browser state presents drafts and progress; server code authenticates, validates and owns mutations. PostgreSQL stores durable delivery, usage, billing and recovery state.\n\nInngest orchestrates work. Gmail accepts messages. Dodo provides hosted billing. Private Blob storage holds PDFs in production; development can use local storage. These services cannot participate in one shared transaction.', 'src/lib/actions.ts','export async function submitCampaign',diagram='flowchart TB\n UI[Browser UI] --> SA[Server actions and API routes]\n SA --> DB[(PostgreSQL via Prisma)]\n SA --> Q[Inngest]\n Q --> W[Delivery and maintenance workers]\n W --> DB\n W --> G[Gmail API]\n W --> S[Private PDF storage]\n D[Dodo signed webhook] --> SA'),
 sec('Stack and responsibility','Version declarations describe this checkout, not an endorsement of the newest library version. See the dependency ledger for declared and locally installed versions. A package confirms implementation use; it does not prove why its author chose it.', 'package.json','"dependencies"',table=[['Layer','Implementation','Role'],['Framework','Next.js 16.4.3 / React 19.3.0 declared','Pages, actions, routes, UI'],['Identity','next-auth 5 beta','Google OAuth and JWT sessions'],['Data','PostgreSQL / Prisma 7.10.0','Relations, transactions, row locks'],['Work','Inngest 4.22.0','Events, durable steps, schedules'],['Delivery','googleapis / gmail-mime alias','Token preparation and MIME sending'],['Billing','dodopayments 2.55.0 / standardwebhooks','Hosted checkout and signed ingress'],['Validation','Zod 4.6.5','Runtime input validation'],['UI','Tailwind / Radix / lucide-react','Styling and accessible primitives']]),
 sec('Module map','src/app contains pages and provider endpoints. src/components holds page-level interactions and reusable UI. src/lib contains policy and business operations. prisma/schema.prisma expresses the current models; migrations record evolution. tests and scripts capture failure contracts, disposable database verification and operator tasks.\n\nINFERRED tradeoff: keeping these concerns in one Next.js application reduces the number of deployable units to coordinate. Evidence is co-location and imports, not an architecture decision record promising lower cost.', 'src/app/api/inngest/route.ts','functions:'),
 sec('Durability over publication','submitCampaign commits campaign and reservation rows before dispatching events. Publication failure is caught; the rows remain discoverable. Reconciliation repairs publication using the same delivery identity with a new dispatch generation.\n\nThe durable outbox is a pattern: commit the intent locally, then recover publication to another system. It does not make publication and Gmail acceptance atomic.', 'src/lib/actions.ts','// Database rows are the durable outbox')])
page('database','Database','Models, constraints, accounting identities and the migration history.', 'Explain why a Send and a UsageReservation are separate: message history can disappear while accounting identity must survive.',[
 sec('The relational core','A User owns contacts, templates, campaigns, attachments and usage records. A Campaign selects a template and optionally an attachment; each Send represents one recipient snapshot and its delivery state. The contact relation remains, but recipient and rendered-message fields are stored on Send so later edits do not rewrite the queued message.\n\nContact email uniqueness is per user. Campaign idempotency is scoped to userId. Send.mimeMessageId and UsageReservation.deliveryKey have uniqueness constraints. These constraints complement locking and policy checks.', 'prisma/schema.prisma','model Campaign',diagram='erDiagram\n User ||--o{ Contact : owns\n User ||--o{ Template : owns\n User ||--o{ Campaign : creates\n Template ||--o{ Campaign : selected\n Campaign ||--o{ Send : snapshots\n Contact ||--o{ Send : recipient\n Send ||--o| UsageReservation : accounts\n User ||--o{ UsagePeriod : owns\n UsagePeriod ||--o{ UsageReservation : buckets'),
 sec('Accounting that survives history deletion','UsagePeriod holds daily/monthly counters and period boundaries. UsageReservation holds stable delivery identity, two period references, a status, claim token and lease. Deleting a Send sets its reservation link to null; it does not erase the charge. UsageImportEvidence retains content-free historical evidence.\n\nDeliveryReceipt preserves minimal successful-delivery evidence after message-history removal. Its recipient address supports repeat-send checks. History deletion and account deletion are different retention operations.', 'prisma/schema.prisma','model UsageReservation'),
 sec('All models and all migrations','The schema atlas below covers every model and migration in this snapshot. Read migration SQL before reasoning about old data: additive columns, data backfills and subsequent corrections matter beyond the final schema. Migrations that share a timestamp prefix are distinct directories and both belong to the history.\n\nThe initialization of SystemControl and later billing binding guards are operationally significant. Local reset scripts intentionally preserve SystemControl and migration metadata.', 'prisma/migrations/20261111010000_dodo_binding_null_guard/migration.sql'),
 sec('Transactions and owner locks','withUsageTransaction serializes an owner’s usage changes with a PostgreSQL row lock. Reservation, claim, confirm and release operations run within that owner context. Period references include user identity to prevent linking a reservation to another tenant’s period.\n\nINFERRED tradeoff: per-owner serialization simplifies quota correctness under concurrent submissions but limits throughput for a single owner. The source supplies the locking design, not measured contention or capacity.', 'src/lib/usage-ledger.ts','export async function withUsageTransaction'),
 sec('Billing, administration and deletion records','BillingSubscription and CheckoutAttempt can outlive their User relation through SetNull and owner snapshots. BillingWebhookEvent is an inbox keyed by unique webhookId. AdminAuditLog records actor and target snapshots, reason, request identity, and before/after state.\n\nAccountDeletionJob deliberately has no User foreign key: recovery must continue after User content is removed. Retained recovery and financial records need their own lifecycle; cascading everything would destroy recovery evidence.', 'prisma/schema.prisma','model AccountDeletionJob')])
page('authentication','Authentication','Google consent, manual persistence, JWT sessions and encrypted server credentials.', 'Separate identity, Gmail authorization and entitlement. Being signed in does not imply permission to send.',[
 sec('OAuth and session identity','OAuth delegates authorization to Google. The normal Google provider requests openid, email, profile and gmail.send with offline access and consent. The signIn callback requires a verified email and Google subject, and checks deletion tombstones.\n\nThe app selects JWT sessions, meaning the session is backed by a signed/encrypted token managed by Auth.js rather than a session row in this schema. User persistence is manual inside the jwt callback. There is no Prisma adapter configuration in auth.ts. An unrelated existing email owner is never silently linked.', 'src/auth.ts','session: { strategy: "jwt" }',diagram='sequenceDiagram\n participant U as User\n participant A as Auth.js\n participant G as Google\n participant DB as PostgreSQL\n U->>A: Sign in\n A->>G: Consent and offline scope request\n G-->>A: Verified profile and credentials\n A->>DB: Check tombstone and persist user\n A-->>U: JWT session with user ID'),
 sec('What the callbacks persist','The jwt callback finds users by googleId, locks an existing user, checks for deletion and rejects unrelated email collisions. It normalizes email, records granted scopes and send-only consent time, and computes gmailAuthorized from the scope plus refresh credential availability.\n\nA new refresh token is encrypted with the owner UUID before persistence. If Google omits a refresh token, the existing encrypted value can remain usable. The session callback rechecks User existence and deletion state before exposing a usable session user ID.', 'src/auth.ts','async jwt'),
 sec('Encryption and key rotation','AES-256-GCM is authenticated encryption: ciphertext includes a tag that detects tampering. The v2 envelope contains version, key ID, random 12-byte IV, tag and ciphertext. Additional authenticated data binds the version, key ID, credential purpose and owner UUID. Copying v2 ciphertext to a different owner fails decryption.\n\nLegacy v1 decryption uses TOKEN_ENCRYPTION_KEY; v2 resolves the identified key without falling back. rotateTokenPage scans User credentials and unexpired deletion credentials, defaults to read-only, and applies compare-and-swap updates so a concurrent reconnect wins. Retain old keys for backups until a restore exercise proves retirement safe.', 'src/lib/crypto.ts','export function encryptToken'),
 sec('Authenticated mutations and fresh admin identity','requireUser reads the current session and database owner; missing or deletion-pending users redirect home. Business operations still need entitlement and resource-ownership checks. A UUID alone is not authorization.\n\nAdmin access uses a distinct Google provider and checks fresh reauthentication for mutations. The restricted admin connection verifies database privileges before allowing operations. Do not equate an isAdmin UI check with this complete boundary.', 'src/lib/admin/auth.ts','export async function requireAdmin'),
 sec('Preparing Gmail without implicit replay','gmailForUser decrypts the refresh token on the server, explicitly obtains an access token, then replaces OAuth credentials with that access token only. The returned object exposes only messages.send. This prevents token refresh from silently replaying a rejected send request.\n\nSend-only v1 cannot read a mailbox: canReadGmail returns false, and reply-check compatibility functions return disabled/no-op results. Repository files cannot establish Google verification status or provider approval for a production project.', 'src/lib/gmail.ts','export async function gmailForUser')])
page('sending','Sending','From immutable campaign snapshots to a single Gmail submission.', 'Never promise exactly-once email. Explain local duplicate protection and what happens when Gmail acceptance cannot be observed.',[
 sec('Campaign admission','submitCampaign authenticates and consumes the campaign rate budget. createCampaign parses input, locks the owner through withUsageTransaction, checks an existing idempotency key, Gmail authorization, controls and plan limits.\n\nThe transaction checks template ownership and availability, contacts and repeat-send evidence. Already pending or uncertain recipients are skipped; previously successful recipients need explicit resend selection. A duplicate idempotency key returns the existing campaign instead of creating another one.', 'src/lib/campaigns.ts','export async function createCampaign',diagram='flowchart LR\n A[Validate and authenticate] --> B[Owner lock]\n B --> C[Check idempotency and policy]\n C --> D[Snapshot each recipient]\n D --> E[Reserve usage and commit]\n E --> F[Dispatch individual events]'),
 sec('Current-limit batch behavior','The schema caps recipientIds at 10 and rejects duplicates. With paidGatingEnabled true, createCampaign additionally enforces 3 recipients for Free or 10 for Premium. Free daily/monthly allowances are 3/15; Premium 20/300. Available capacity can be lower because other reservations already occupy it.\n\nWith paid gating disabled, client entitlements expose 10 recipients, no monthly limit and the legacy rolling-24-hour cap of 200. The ledger still records state. Do not combine legacy rolling usage with UTC calendar counters as if they were equivalent.', 'src/lib/entitlements.ts','limits: {'),
 sec('Personalization and MIME','The allowed placeholders are {{name}}, {{company}} and {{role}}. The campaign stores rendered subject/body, recipient details, template name, message ID and attachment selection. A subject containing newlines after rendering is rejected.\n\nMIME is the email wire format. buildMime uses the gmail-mime package alias for Nodemailer MailComposer. It creates text and HTML parts, an explicit Message-ID, and an optional PDF attachment, then base64url-encodes the result. Each message has one To recipient; the code adds no CC or BCC. File and URL fetching are disabled in the composer.', 'src/lib/gmail.ts','export async function buildMime'),
 sec('Prepare, claim, submit, settle','deliverOne first reads current delivery state and performs preflight checks under a short owner lock. It prepares credentials, attachment bytes and MIME outside the lock. It then rechecks fresh controls and entitlement at the final claim; an intervening suspension or quota boundary can still stop delivery.\n\nclaimUsage moves the reservation into an attempting state and returns a claim token. Only after the final claim commits does messages.send run, with SDK retries disabled. Success records Gmail IDs and confirms accounting. A lease is a temporary exclusive claim, not permission to resend after it expires.', 'src/lib/inngest.ts','const preflight = await check(false)',diagram='sequenceDiagram\n participant W as Worker\n participant DB as Database\n participant G as Gmail\n W->>DB: Preflight under owner lock\n W->>G: Prepare access token\n W->>W: Read PDF and build MIME\n W->>DB: Recheck and claim\n W->>G: One send request\n G-->>W: Acceptance or failure\n W->>DB: Confirm, release, or retain uncertainty'),
 sec('Definite failure versus uncertainty','Preparation failures and definite provider rejections finish without an automatic sending retry and release appropriate reservations. Credential/domain failures pause the owner; rate limits pause owner or project work according to classification and provider deadlines. Other queued work can be deferred.\n\nA timeout, network failure, unknown provider outcome, lost acceptance persistence, or an expired attempting lease may mean Gmail accepted the message. Such work becomes UNCERTAIN, retains accounting and never automatically re-enters READY. A stable MIME Message-ID aids identity; it is not a provider guarantee of deduplication.', 'src/lib/inngest.ts','const uncertain = accepted'),
 sec('Pacing and recovery','Normal sends are spaced about five seconds apart, and the worker serializes per owner. Pacing waits happen before an attempt; they are not repeat submissions. Queues expire after 24 hours. Deferred publication and eligibility are revisited by hourly reconciliation.\n\nRead queue copy carefully: “retries” can mean publishing durable queued work, while the email worker has retries: 0 and never repeats an ambiguous send. Manual reply marking is not delivery reconciliation and does not search Sent mail.', 'src/lib/inngest.ts','export const sendEmail')])
page('inngest','Inngest','Eight registered functions, durable steps, concurrency and recovery.', 'Distinguish orchestration retries, publication recovery, pacing waits and another Gmail sending attempt.',[
 sec('Registration is the authoritative list','/api/inngest exports GET, POST and PUT from serve with exactly eight registered functions. Imports elsewhere do not create a ninth registration. Provider callbacks use the service signature boundary, not a user session. Actual deployed registration and signing configuration require operational verification.', 'src/app/api/inngest/route.ts','functions:',diagram='flowchart TB\n E[Queued email event] --> S[sendEmail]\n H[Hourly] --> Q[quotaReconciliation]\n D[Daily schedules] --> M[Maintenance and sweeps]\n F[Every four hours] --> B[billingMaintenance]\n Q --> E\n M --> A[Per-owner cleanup or deletion event]'),
 sec('All eight functions','Cron expressions below are the source schedules, described in UTC in the rollout documentation. Event-driven workers validate UUID data and serialize by user where configured.', 'src/app/api/inngest/route.ts','functions:',table=[['Export / ID','Trigger','Purpose'],['sendEmail / send-individual-email','mailloop/email.queued','One delivery; retries 0; concurrency 1 per owner'],['quotaReconciliation / quota-reconciliation','0 * * * *','Settle evidence, expire leases, repair publication'],['maintenance / maintenance','0 3 * * *','Discover owners with obsolete PDFs'],['accountMaintenance / account-maintenance','mailloop/account.maintenance','Recheck and clean attachments per owner'],['deletionJobSweep / account-deletion-jobs','0 2 * * *','Expire credentials; discover deletion jobs'],['deletionJobWorker / account-deletion-worker','mailloop/account.deletion','Run durable account deletion'],['rateLimitCleanup / rate-limit-cleanup','0 4 * * *','Bounded cleanup of old rate budgets'],['billingMaintenance / billing-maintenance','0 */4 * * *','Lifecycle sweep, recovery; daily reconciliation']]),
 sec('Steps are durable work boundaries','sendEmail uses step.run for each pacing round and step.sleepUntil when it must wait. The function has automatic retries disabled and ends on done, uncertain or deferred. Deferred work is discoverable for future publication.\n\nMaintenance discovery pages users inside a step and emits batches of at most 100 owner events. Account maintenance rechecks deletion status, because events can arrive after account state changes.', 'src/lib/inngest.ts','async ({ event, step })'),
 sec('Reconciliation and maintenance','Quota reconciliation pages owners, repairs accounting and publication, and turns abandoned claims into uncertainty. Attachment maintenance protects current PDFs and PDFs referenced by queued, attempting or uncertain sends. Physical deletion is marked separately so failure can be retried later.\n\nBilling maintenance sweeps lifecycle state, recovers inbox/checkout work every four hours and reconciles at UTC midnight. It skips Vercel previews; it must not be assumed to run merely because the function exists.', 'src/lib/billing/schedules.ts','export const billingMaintenance'),
 sec('Why background work exists','CONFIRMED tradeoff: the billing schedule comment explicitly cites keeping baseline executions within Inngest Free’s monthly allowance as the reason for a four-hour cadence. That cadence allows recovery delay. It is not an observed service-level guarantee.\n\nINFERRED tradeoff: batching cleanup discovery reduces orchestration overhead relative to waking every account individually, while delays and backlog can increase. Measure step/run consumption and provider behavior before estimating capacity.', 'src/lib/billing/schedules.ts','// One invocation every four hours')])
page('payments','Payments','Hosted checkout, signed events, durable receipts and verified entitlement.', 'A browser return means navigation succeeded. Explain how verified provider evidence becomes access.',[
 sec('Explicit test and live environments','billingConfig accepts only explicit test_mode or live_mode, requires server credentials/product/business configuration, rejects custom base URL/header overrides, and validates a canonical origin. Live mode requires HTTPS.\n\nAGENTS.md and parts of older hardening/test guides describe test-only billing. Current config and docs/dodo-live-rollout.md support both environments. A database is bound to one environment and business; changing environment variables does not convert test objects into live ones.', 'src/lib/billing/config.ts','export function billingConfig',diagram='sequenceDiagram\n participant U as Browser\n participant A as App\n participant D as Dodo\n participant DB as Database\n U->>A: Authenticated checkout request\n A->>DB: Bind mode and record attempt\n A->>D: Create hosted checkout\n A-->>U: Checkout URL\n D->>A: Signed webhook\n A->>DB: Commit receipt\n A->>D: Verify current provider state\n A->>DB: Update subscription observation\n U->>A: Poll access status'),
 sec('Rollout guards and hosted prices','ensureBillingBinding locks SystemControl and binds only a clean unbound database. Existing provider records in an unbound database require review; a mode or business mismatch fails closed. Checkout has a separate billingCheckoutEnabled switch. Turning off new checkout must not stop management and recovery of existing subscriptions.\n\nverifyBillingProduct checks a monthly recurring catalog: USD 599 minor units, an India INR 29900 rule, tax inclusive, no trial/add-ons/discounts/PPP, and the expected long subscription term. Hosted quotes and final tax presentation remain provider-dependent and must be verified operationally.', 'src/lib/billing/store.ts','export async function ensureBillingBinding'),
 sec('Signature verification before storage','The webhook route limits the body to 256 KiB and requires webhook-id, webhook-signature and webhook-timestamp. Standard Webhooks verifies the exact raw body with timestamp tolerance before any payload is trusted. Missing/invalid signature returns 401; unavailable configuration returns 503.\n\nThe route does not use a user session: a valid provider signature authenticates the callback. Never verify reserialized JSON or trust a client return URL as payment evidence.', 'src/app/api/webhooks/dodo/route.ts','let verified: unknown;'),
 sec('Durable inbox and reconciliation','storeBillingEvent validates the business ID, normalizes supported data, hashes the raw payload and upserts by webhookId. Unsupported events can be IGNORED; recognized unusable data is QUARANTINED. Reusing a webhook ID with a different payload hash returns a conflict.\n\nAfter the inbox commits, after() attempts processing. A lost processing opportunity is recoverable from committed state and nextAttemptAt. Lifecycle processing and scheduled reconciliation use server-side provider observations rather than redirect parameters. Financial state is not simply the last browser event.', 'src/lib/billing/webhooks.ts','export async function storeBillingEvent'),
 sec('Effective plan is a decision, not a badge','getEffectivePlan considers deletion/suspension, active overrides, grandfathering and resolveSubscriptionLifecycle. A valid paid observation requires meaningful provider period boundaries. PAST_DUE grace extends the operational end of the same allowance; it does not mint another allowance. An unresolved active boundary pauses sending.\n\nCancellation at period end can preserve access until the verified deadline. A later downgrade rechecks queued campaigns; whole eligible unsent remainders compete for Free capacity. Attempted and uncertain evidence is not refunded by downgrade.', 'src/lib/subscription-lifecycle.ts','export function resolveSubscriptionLifecycle'),
 sec('Maintenance and account deletion','Recovery scans checkout attempts and webhook receipts; reconciliation refreshes provider observations. Billing maintenance runs every four hours and performs daily reconciliation at midnight UTC. Cancellation, portal and status routes remain authenticated and rate limited.\n\nDeletion recovery retains provider IDs and a deadline-limited revocation credential in an independent job so billing cancellation and credential cleanup can progress even after message content is gone. The handbook never performs real billing operations.', 'src/lib/billing/jobs.ts','export async function recoverBilling')])
page('frontend','Frontend','Page responsibilities, server/client boundaries and honest delivery feedback.', 'Explain where UI convenience ends and the server’s authority begins. Hiding a button is not enforcing a plan.',[
 sec('Workspace page walkthrough','The authenticated workspace layout obtains the owner and access/usage state, then wraps page navigation and interactive controls. Server pages prepare durable data; client components handle drafts, filtering, selection and feedback. Inspect page files alongside their components when tracing behavior.', 'src/app/(app)/layout.tsx',table=[['Page','Reader task','Implementation entry'],['Compose','Choose contacts/template, inspect personalized previews, queue','src/app/(app)/compose/page.tsx'],['Contacts','Create/edit/archive contacts and import CSV','src/app/(app)/contacts/page.tsx'],['Templates','Edit and select plan-available templates','src/app/(app)/templates/page.tsx'],['History','Review delivery states, shortlist, mark replied','src/app/(app)/history/page.tsx'],['Usage','Understand allowances and current plan','src/app/(app)/usage/page.tsx'],['Settings','Manage Gmail, PDF, preferences, data and billing','src/app/(app)/settings/page.tsx'],['Admin','Restricted operator views and audited changes','src/app/(admin)/admin/page.tsx']]),
 sec('Public and return pages','The landing and pricing pages explain the product and plans; help, contact, privacy and terms provide public support/policy surfaces. Loading and error files define route-level feedback. The checkout return and settings billing return routes coordinate a status view after hosted navigation.\n\nDo not infer that a return page grants access. Read status polling and the server’s entitlement state. The complete page and API route inventory below links the actual file paths.', 'src/app/(app)/settings/billing/return/page.tsx'),
 sec('Compose and progress','Compose coordinates contact selection, role values, template previews, resume attachment and submit state. The server validates those choices again. Campaign progress and sending-status components communicate queued and terminal outcomes. A client timer cannot prove provider delivery.\n\nINFERRED tradeoff: server-rendered data plus focused client controls provides a useful initial view with local interactivity, but freshness must be handled explicitly after mutations and during long queues.', 'src/components/compose.tsx','export function'),
 sec('Themes, styles and reusable primitives','The source uses semantic theme tokens, Tailwind utilities, retained scoped CSS and Radix-backed UI primitives. appearance-control, preferences and theme components preserve user preferences, while dedicated skeleton/loading components keep route transitions coherent.\n\nDesign documents record appearance constraints and browser screenshot expectations. They establish design intent and test coverage, not proof that every browser or assistive technology has been verified in production.', 'docs/tailwind-styling.md'),
 sec('Feature feedback and source authority','Plan controls explain limits in the UI through entitlement projections, feature locks, allowance cards and upgrade dialogs. Server actions and workers remain authoritative when a tab is stale. Suspended and deletion-pending users require fresh server decisions.\n\nThe source browser is a snapshot rather than a runnable copy of Mailloop. Redacted literals may no longer form executable code. This handbook’s controls store only local learning progress and theme preference.', 'src/lib/entitlements.ts','export function getClientEntitlements')])
page('function-reference','Function / API Reference','Compiler-extracted declarations and call sites, with reviewed contracts for core operations.', 'Trace caller → contract → side effects → failure behavior. A function name alone is not an explanation.',[
 sec('How to use the inventories','The TypeScript compiler API visits every function body in the sanitized first-party TypeScript/JavaScript files: named declarations, methods, assigned arrow functions, inline callbacks, hooks, server actions and Inngest handlers. Each record carries file, inclusive lines, parameter text, returns, calls and structural caller candidates.\n\nCall candidates are deliberately conservative: matching a callee name is not type-resolved reachability. Framework routing, JSX callbacks, higher-order registration, aliases and dynamic properties may supply callers that static analysis cannot resolve. Records explicitly flag this limitation. Source excerpts and reviewed core contracts below are the basis for behavioral explanation.', 'src/lib/actions.ts','export async function submitCampaign'),
 sec('Core contracts','The reviewed contracts connect inputs, outputs, side effects and callers for the critical path. The full inventory includes implementation details and tests; use its filters to distinguish runtime functions from test callbacks. For unreviewed helpers, structural summaries are navigation aids, not invented behavioral guarantees.', 'src/lib/usage-ledger.ts','export async function claimUsage'),
 sec('Route contracts and authentication','API inventory entries include declared HTTP methods and the exact route file. Normal user endpoints authenticate sessions; Auth.js, Inngest and Blob/Dodo provider callback branches have distinct verification boundaries. Review the full handler before applying the “all routes need a session” shorthand.\n\nStatus codes, response shapes and ownership queries are in the linked snippets. There is no handbook backend. The source-browser query string selects an already bundled sanitized snapshot file.', 'src/app/api/resume/blob/route.ts')])
page('walkthroughs','Walkthroughs','Six end-to-end traces with numbered source-linked steps and supported failures.', 'For each trace, name the durable commit and one failure before and after that commit.',[
 sec('Six routes through the code','Use the six child walkthroughs to rehearse real behavior: sign-in, a current-limit campaign, one delivery, resume attachment, Premium upgrade and account deletion. The original brief is represented only by the supplied plan; these six cover the important system boundaries without inventing unsupported features.', 'src/lib/actions.ts','export async function submitCampaign',diagram='flowchart LR\n A[Identity] --> B[Prepare campaign]\n B --> C[Individual delivery]\n D[PDF lifecycle] --> B\n E[Verified billing] --> B\n F[Account deletion] --> G[Durable recovery]'),
 sec('Choose a trace','A three-recipient Free campaign replaces the outdated 15-recipient example. A Premium campaign can contain up to ten recipients if remaining capacity allows. Queuing does not promise immediate delivery, acceptance or an automatic retry after uncertainty.', 'src/lib/validation.ts','export const campaignSchema',items=['Sign in and reconnect Gmail → /handbook/walkthrough-sign-in/','Queue a current-limit campaign → /handbook/walkthrough-campaign/','Deliver one message → /handbook/walkthrough-delivery/','Upload and retain a PDF → /handbook/walkthrough-attachment/','Upgrade through hosted checkout → /handbook/walkthrough-upgrade/','Delete an account with recovery → /handbook/walkthrough-deletion/'])])
page('tradeoffs','Tradeoffs','Separate decision evidence from plausible implementation consequences.', 'Say “the implementation suggests” when intent is unknown. Do not turn a dependency choice into a personal story.',[
 sec('Confirmed: conservative sending','CONFIRMED: code comments and usage-ledger rollout guidance explicitly state that an expired lease never authorizes a resend and Gmail/database cannot guarantee atomic exactly-once acceptance. The policy retains ambiguous charges and asks the user to check Sent.\n\nBenefit: fewer duplicate submissions after unknown outcomes. Cost: a genuinely unsent message can remain unresolved and occupy allowance. Alternative: automatically retry uncertain sends, accepting duplicate risk. The source intentionally chooses the conservative policy.', 'docs/usage-ledger-rollout.md','Already-sent and uncertain deliveries'),
 sec('Confirmed: send-only Gmail','CONFIRMED: canReadGmail is hardcoded false and the source labels v1 send-only. Restricting the exposed Gmail client to messages.send is explicit. Reply checks return disabled results.\n\nBenefit: runtime cannot inspect mailbox content through these paths. Cost: automatic reply/bounce detection and Sent reconciliation are unavailable. Manual reply status remains a user assertion, not observed mailbox evidence.', 'src/lib/capabilities.ts','// No token scope'),
 sec('Confirmed: schedule cost versus recovery time','CONFIRMED: the billing schedule comment names Inngest Free’s execution allowance as a reason for the four-hour cadence. Daily provider reconciliation runs on the midnight invocation.\n\nBenefit: fewer baseline executions. Cost: delayed recovery of missed processing. Do not quote a measured monthly bill or user capacity without running representative traffic and checking provider plans.', 'src/lib/billing/schedules.ts','// One invocation every four hours'),
 sec('Inferred: PostgreSQL locking and Prisma','INFERRED: relational constraints plus explicit row locks support per-owner correctness while Prisma supplies typed queries. Benefit: campaign and reservation changes can commit together. Cost: contention and transaction complexity. An in-memory counter would be simpler but would not survive multiple processes or restarts.\n\nThe use of Prisma is confirmed by imports and configuration. The reason it was selected over another ORM is unknown; describe the demonstrated capabilities rather than claiming author motivation.', 'src/lib/usage-ledger.ts','export async function withUsageTransaction'),
 sec('Inferred: one application and hosted services','INFERRED: keeping pages, actions, webhook ingress and worker registrations in one codebase makes cross-layer tracing and changes easier. Cost: changes in shared code can affect several execution paths and require coordinated deployment.\n\nINFERRED: hosted Dodo checkout avoids building payment collection UI, while adding provider availability, signed-event and reconciliation dependencies. Private Blob storage separates PDF bytes from database metadata, but cleanup becomes a distributed lifecycle.', 'src/lib/billing/checkout.ts','export async function'),
 sec('Design comparisons to rehearse','Compare JWT sessions with database sessions: current identity tokens carry IDs but callbacks still check database deletion state. Compare queued orchestration with synchronous request sending: background work survives UI navigation but needs publication recovery. Compare snapshots with live template reads: snapshots preserve approved content but retain message data that deletion must explicitly handle.', 'src/auth.ts','async session',table=[['Choice','Shown implementation','Alternative and cost'],['Message content','Per-send immutable snapshot','Live template read can change queued content'],['Usage','Durable reservations with owner lock','Naive count-then-send races'],['Unknown outcome','Retain charge and prevent resend','Retry risks duplicate acceptance'],['Provider events','Durable inbox and reconciliation','Redirect-only access is untrusted'],['Admin data','Restricted database role','Owner role exposes private message data']])])
page('security-reliability','Security / Reliability','Existing controls, confirmed limitations and deployment-dependent risks.', 'Explain a concrete failure path and its control. Keep confirmed weaknesses separate from hypotheses.',[
 sec('Authentication is only one boundary','Normal mutations authenticate the owner, validate input and scope resource queries by userId. Rate budgets are admitted before business parsing for protected operations. Webhooks authenticate with provider signatures; Blob completion verifies its service callback. Admin mutations add fresh identity, restricted SQL privileges and an audit record.\n\nThese are implementation controls. They do not prove every deployment has correct secrets, least-privilege grants or provider settings. No penetration test or production audit is claimed here.', 'src/lib/admin/auth.ts','export async function requireAdmin'),
 sec('Confirmed limitations','Confirmed limitation: Gmail acceptance and database persistence are not atomic. Unknown outcomes cannot be resolved by mailbox reads because send-only v1 disables them. This can retain usage for a message that did not actually arrive.\n\nConfirmed operational gap: automatic operator alert delivery and monitoring jobs were removed in the documented hardening evolution. Safe logs and persisted recovery state remain; operators must arrange observation externally. Do not infer that an alert integration exists.', 'docs/minimum-hardening.md','Automatic'),
 sec('PDF and content safeguards','PDF validation enforces a 5 MiB size bound, MIME type and %PDF- prefix. Storage paths are restricted to the owner’s resume prefix, filenames strip control characters, and private Blob reads have timeouts. MailComposer cannot read arbitrary URLs or files.\n\nPossible risk: size/type/magic checks do not establish that a PDF is harmless; the shown validation is not a malware scanner. This is a possible content risk, not evidence of an exploit. The actual provider storage configuration is externally dependent.', 'src/lib/validation.ts','export function validatePdf'),
 sec('Credentials, logs and key recovery','Refresh tokens are encrypted server-side with owner-bound v2 authenticated encryption. Safe logging accepts bounded codes and identifiers instead of raw provider errors, email bodies, addresses or credentials. A key rotation command covers retained deletion credentials too.\n\nExternally dependent: key provisioning, backup retention, restore exercises and secret access controls. Encryption does not protect against a fully compromised process that holds both database access and keys. The repository cannot establish actual backup readiness.', 'src/lib/observability.ts','export function safeLog'),
 sec('Rate limits and predictable degradation','The database-backed limiter uses rolling windows, row locks, bounded timestamp arrays and database time. Limiter/database failures block protected operations rather than silently admitting them. HTTP routes return 429 with Retry-After or 503; actions return structured failure codes.\n\nProvider throttling is separate from the app allowance. Reconnecting Gmail can clear a credential/policy pause but never restores cancelled sends, resets app usage or removes suspension.', 'src/lib/rate-limit.ts','export async function consumeBudgets'),
 sec('Test evidence has boundaries','Tests cover token envelopes, MIME, usage claims, webhook signatures, deletion, privacy and database migrations. Browser suites exercise themes, plan gates, forms and status views. Test files are evidence of intended contracts; they are not proof those tests currently pass or that production behaves identically.\n\nThis handbook runs its own static and browser checks without starting Mailloop, touching its database or using any provider credentials.', 'tests/gmail-boundary.test.ts',diagram='flowchart LR\n A[Known unsent] --> B[Release reservation]\n C[Provider accepted] --> D[Confirm usage]\n E[Unknown outcome] --> F[Retain charge and block resend]\n G[Deployment evidence absent] --> H[Mark externally dependent]')])
page('scaling','Scaling','Bottlenecks, correctness constraints and measurement plans grounded in code.', 'Start with current constraints and proposed measurements. Do not invent requests per second, email volume or cost savings.',[
 sec('Current concurrency and cost drivers','The send function limits concurrency to one per user and normal pacing is about five seconds. Gmail/provider limits, preparation latency, database transactions and scheduled recovery all affect throughput. A five-second interval is a policy constant, not a measured end-to-end rate.\n\nThe platform may run many owners concurrently, but configured provider/account limits and Inngest capacity are external. Measure database lock waits, provider latency, event delays and uncertain-outcome rate before stating capacity.', 'src/lib/inngest.ts','concurrency: { limit: 1'),
 sec('Database pressure and indexing','Owner locks deliberately serialize competing usage operations. Schema indexes support status/availability/lease discovery and tenant queries. Reconciliation and maintenance page by stable IDs; rate-limit cleanup uses SKIP LOCKED with bounded batches.\n\nINFERRED tradeoff: more detailed accounting and indexes improve recoverability while increasing write work. Assess execution plans and realistic contention before changing indexes or widening parallelism. Removing owner serialization without a replacement can break quota invariants.', 'src/lib/rate-limit-jobs.ts','export async function cleanupExpiredRateLimits'),
 sec('Queue backlogs and lifecycle capacity','Queues have original expiry deadlines; republishing must not extend them. Hourly recovery introduces visible delay after dispatch failure. Cleanup deletes at most ten obsolete PDFs per owner pass, so large backlogs take multiple passes. Billing recovery and account-deletion recovery have their own state and retry schedules.\n\nA useful scaling dashboard would expose oldest READY age, publication delay, expired leases, unresolved UNCERTAIN age, counter drift, cleanup backlog and billing inbox age. This is a proposed measurement plan, not an existing dashboard claim.', 'src/lib/storage.ts','export async function cleanupAttachments',diagram='flowchart LR\n A[Measure queue and lock waits] --> B[Identify limiting boundary]\n B --> C[Change one bounded stage]\n C --> D[Verify quota and duplicate invariants]\n D --> E[Measure with representative load]'),
 sec('Safe next steps','A proposed load exercise uses disposable PostgreSQL, fake provider responses and representative multi-owner campaigns. Include concurrent submit, lost event publication, a token-preparation delay crossing a quota boundary and a lost acceptance write. Record latency distributions and invariant violations.\n\nDo not test production sending capacity by generating real cold email. Any architecture change must preserve stable delivery identity, tenant boundaries, accounting retention and uncertainty semantics. Sharding, partitioning or a dedicated queue are options to evaluate after measuring the actual constraint.', 'scripts/test-usage-db.ts')])
page('interview-prep','Interview Prep','Evidence-based answers, deeper follow-ups, flashcards and self-checks.', 'Use the short answer first; expand with a concrete code boundary and a failure case. Add personal experience only when it is your own.',[
 sec('An honest answer framework','Use four parts: what the feature does, the important implementation boundary, the tradeoff and how you would verify it. Say “the code implements” for repository evidence. Say “I would measure” for an unrun experiment.\n\nFor personal questions such as “What was your biggest challenge?”, do not invent authorship or a production incident. A defensible framework is: “A technically demanding area here is ambiguous Gmail acceptance. The implementation uses leases, durable accounting and no automatic resend. My own contribution was [your actual work], verified by [your actual evidence].”', 'src/lib/inngest.ts','// Preflight and the final claim'),
 sec('Practice in three passes','The question bank below contains short answers, deeper explanations and revision links. Reveal an answer before marking your confidence; use flashcards for recall and the quiz for discriminating between plausible choices. Progress stays in this browser only.\n\nFirst explain the happy path. Next explain failed publication, definite rejection and uncertain acceptance. Finally compare designs without inventing why the original author made a choice.', 'src/lib/inngest.ts','export const sendEmail')])
page('glossary','Glossary','Plain-language definitions linked from the chapters.', 'Define a term by its role in this system, then point to the actual implementation.',[
 sec('Read terms in context','The glossary defines implementation vocabulary used throughout this guide. Terms are linked at first visible mention in chapter paragraphs. Some are general concepts, but each definition is tied to how this snapshot uses it. A lease is not a retry license; a session is not a Gmail credential; an entitlement is not a client badge.', 'src/lib/usage-ledger.ts','export async function claimUsage')])
page('cheat-sheet','Cheat Sheet','The ten concepts to retain and a compact map back to evidence.', 'If you can explain these ten concepts with a failure case each, you have a useful revision foundation. It is not a guarantee of interview readiness.',[
 sec('Ten concepts before an interview','Use this list to find gaps in understanding, then follow the revision links and source. The central invariant is that local state must not pretend to know an external outcome.', 'src/lib/plans.ts','export const PLANS',items=['1. Product: personalized individual Gmail messages for job seekers; no batch CC/BCC.','2. Limits: Free 3/campaign, 3/day, 15/month; Premium 10/campaign, 20/day, 300/period.','3. Legacy flag: gating off uses rolling 200/day and still writes ledger evidence.','4. Identity: Google OAuth + JWT sessions; User persistence is manual.','5. Credentials: server-only encrypted refresh tokens; access tokens are prepared before final claim.','6. Admission: owner lock, idempotency, tenant checks, immutable send snapshots and reservations.','7. Delivery: prepare outside lock, recheck, claim, one Gmail request, then settle.','8. Uncertainty: retain accounting and block automatic resend; exactly-once acceptance is not guaranteed.','9. Billing: explicit mode/business binding, signed durable inbox, provider verification and entitlement decisions.','10. Recovery: eight Inngest registrations cover delivery, reconciliation, attachment cleanup, deletion, billing and rate budgets.']),
 sec('Fast distinction table','Keep these distinctions explicit. Most misleading explanations blur two states that the code deliberately separates.', 'prisma/schema.prisma','enum DeliveryState',table=[['Do not confuse','Why'],['QUEUED and ATTEMPTING','A queued item has not necessarily crossed the send boundary'],['FAILED and definitely unsent','UNCERTAIN may appear with a failed status but needs review'],['History deletion and account deletion','Receipts/accounting can survive history removal'],['Provider period and UTC month','Actual subscriptions use verified provider boundaries'],['Reconciliation and resend','Repairing evidence/publication never licenses ambiguous resend'],['Checkout return and payment proof','Only verified provider evidence can grant paid access'],['Test coverage and production verification','Fixtures cannot establish deployed flags or Google status']]),
 sec('Commands belong to the right project','Handbook commands run inside mailloop-handbook. npm run dev starts the local guide; npm run build validates content and exports out/. npm run source:verify checks that the source checkout still matches its baseline.\n\nMailloop operator scripts shown in the source are explanatory references. They can mutate application data when run with apply flags; this handbook does not run them or require its database, OAuth, Gmail or payment credentials.', 'package.json','"scripts"')])
# Six detailed child flows, each numbered step is independently source-linked.
flows=[
 ('sign-in','Sign in and reconnect Gmail','Trace Google identity through callbacks into a usable local owner.',[
 ('Start Google consent','The normal provider requests offline access and gmail.send. Identity scopes are separate from sending permission.','src/auth.ts','Google({'),
 ('Validate the incoming profile','Require verified email, subject and the expected provider; reject a deletion tombstone or pending deletion.','src/auth.ts','async signIn'),
 ('Persist the owner transactionally','Resolve by googleId, lock an existing user and reject unrelated email collisions. Encrypt a new refresh token against the owner UUID.','src/auth.ts','async jwt'),
 ('Project a session','Expose the owner ID only if User still exists and is not deletion-pending. Reauthentication evidence is distinct from normal Google sign-in.','src/auth.ts','async session'),
 ('Prepare credentials when sending','requireUser authenticates business entrypoints. gmailForUser later checks authorization and refresh availability and prepares an access token.','src/lib/gmail.ts','export async function gmailForUser')],
 'Unverified email or wrong provider is denied; unrelated email collision requires review. Missing send scope or refresh credential means reconnect. A deletion tombstone prevents immediate recreation while cleanup is pending.',
 'flowchart LR\n A[Consent] --> B[Validate identity]\n B --> C[Lock and persist owner]\n C --> D[JWT session]\n D --> E[Later prepare Gmail token]'),
 ('campaign','Queue a current-limit campaign','Replace a 15-recipient batch with an evidence-based three-recipient Free example.',[
 ('Choose three eligible contacts','Assume paid gating is on, three Free daily slots remain and at least three monthly slots remain. Choose a template and roles; attach only an available PDF.','src/lib/plans.ts','export const PLANS'),
 ('Authenticate and admit the request','submitCampaign obtains the owner and consumes the rate budget before calling createCampaign. A failed request may still consume request-rate capacity.','src/lib/actions.ts','export async function submitCampaign'),
 ('Validate the maximum and idempotency','campaignSchema rejects 15 recipients immediately. createCampaign checks an existing owner/key before creating rows; a new four-recipient Free request fails the plan-specific limit.','src/lib/campaigns.ts','const previous ='),
 ('Check ownership and duplicate evidence','Require an available owner template and contacts. Exclude pending or uncertain recipients; require explicit selection for successful-recipient resends.','src/lib/campaigns.ts','const selected ='),
 ('Commit snapshots and reservations','Render each recipient’s message and store a stable Send ID/Message-ID. Campaign creation and reserveUsage occur in one owner transaction.','src/lib/campaigns.ts','const campaign ='),
 ('Publish after commit','Dispatch immediately. If publication fails, keep durable queue rows for hourly repair rather than creating another campaign.','src/lib/actions.ts','// Database rows are the durable outbox')],
 'Fifteen recipients fail schema validation; four Free recipients fail plan enforcement. Missing contacts, unavailable templates, absent roles, unavailable PDF or exhausted capacity prevent a new campaign. Event publication can fail after a successful database commit without losing the durable intent.',
 'flowchart LR\n A[Three Free recipients] --> B[Auth and rate admission]\n B --> C[Policy and owner checks]\n C --> D[Snapshot plus reserve commit]\n D --> E[Publish]\n E --> F[Hourly repair if interrupted]'),
 ('delivery','Deliver one message','Follow one queued Send across the non-atomic Gmail boundary.',[
 ('Load state and refuse repeat submission','Return immediately for terminal, DONE or UNCERTAIN states. An expired ATTEMPTING lease becomes uncertain rather than ready.','src/lib/inngest.ts','export async function deliverOne'),
 ('Perform preflight','Under the owner lock read controls, pauses, expiry, access and accounting readiness. Pacing can wait and capacity can defer before an attempt.','src/lib/inngest.ts','const check ='),
 ('Prepare outside the lock','Obtain an access token, read the campaign-selected PDF and build MIME. Slow network preparation does not hold the owner lock.','src/lib/inngest.ts','const preflight ='),
 ('Recheck and claim','Use a fresh authorization time and controls. claimUsage supplies the token and lease that identify this specific submission.','src/lib/inngest.ts','const claim = await check(true)'),
 ('Send exactly one request','Call Gmail messages.send with retry false. One To recipient is encoded in the MIME message. This is one submission policy, not a guarantee of exactly-once provider acceptance.','src/lib/inngest.ts','const response = await gmail'),
 ('Settle the evidence','Persist success and confirmUsage; release definite rejection, or retain uncertain accounting. Failed settlement is warned and later reconciled.','src/lib/inngest.ts','const uncertain = accepted')],
 'Missing credentials or PDF can fail before submission and release the reservation. A definite Gmail rejection finishes without retry. A timeout after submission or acceptance with failed persistence is uncertain, keeps capacity and never auto-resends.',
 'flowchart TB\n A[READY] --> B[Preflight and prepare]\n B --> C[Final claim]\n C --> D[ATTEMPTING]\n D --> E[Confirmed DONE]\n D --> F[Definite rejection and release]\n D --> G[UNCERTAIN and retain]'),
 ('attachment','Upload and retain a PDF','Separate uploaded bytes, activation, campaign references and physical deletion.',[
 ('Choose the storage branch','Production uses private Blob storage; non-production without Blob can store local files with restrictive filesystem modes. The upload entrypoint authenticates the user.','src/app/api/resume/upload/route.ts'),
 ('Verify Blob callback boundaries','The client-upload route authenticates token generation and relies on verified Blob completion for the provider callback. Do not apply a user-session requirement to the service completion branch.','src/app/api/resume/blob/route.ts'),
 ('Validate and activate','activateResume reads bytes, validates size/type/header, locks the owner, checks availability and stores/selects attachment metadata. Rejected activation tries to discard the unactivated path.','src/lib/storage.ts','export async function activateResume'),
 ('Snapshot the selection','createCampaign records the selected attachment ID; the worker reads that selection rather than the owner’s later replacement PDF.','src/lib/campaigns.ts','const attachment ='),
 ('Retire only unneeded files','cleanupAttachments excludes current PDFs and references from queued, attempting or uncertain work. deletedAt and storageDeletedAt separate logical retirement from completed physical deletion.','src/lib/storage.ts','export async function cleanupAttachments')],
 'An invalid owner path is rejected. Wrong MIME/prefix or oversized PDF fails validation. Suspension/deletion can race with completion and cause discard. Failed physical deletion remains pending; uncertain deliveries can intentionally retain their attachment.',
 'flowchart LR\n A[Private upload] --> B[Read and validate]\n B --> C[Activate under owner lock]\n C --> D[Campaign references PDF]\n D --> E[Protect while unresolved]\n E --> F[Retire and delete when eligible]'),
 ('upgrade','Upgrade through hosted checkout','Separate a hosted return, a durable webhook and a verified paid entitlement.',[
 ('Authenticate the checkout route','The user endpoint validates session/origin and consumes a checkout rate budget before creating a hosted session.','src/app/api/billing/checkout/route.ts'),
 ('Bind mode and verify product','Require explicit config, a matching SystemControl business/environment binding, a valid catalog and the checkout enable flag.','src/lib/billing/store.ts','export async function ensureBillingBinding'),
 ('Record attempt and call provider','Checkout uses durable attempts and idempotency. Uncertain provider creation is recoverable; retrying with an unrelated identity can create duplicate commercial work.','src/lib/billing/checkout.ts','export async function'),
 ('Verify and commit webhook receipt','Verify exact raw bytes, validate business, normalize data and upsert the payload hash by webhookId. Commit before asynchronous processing.','src/app/api/webhooks/dodo/route.ts','let verified: unknown;'),
 ('Process verified provider observations','Lifecycle processing checks provider evidence and updates durable subscription state. Scheduled recovery and reconciliation cover missed processing.','src/lib/billing/lifecycle.ts','export async function processBillingEvent'),
 ('Resolve present access','The return page displays status; entitlement resolution considers effective plan, valid period, override, suspension and deletion. A redirect alone never grants Premium.','src/lib/entitlements.ts','export function getEffectivePlan')],
 'Config/mode binding or catalog mismatch blocks checkout. Invalid signature returns 401; oversized body returns 413. Duplicate identical receipts are idempotent; conflicting webhook ID/hash is 409. Processing outages leave durable recoverable receipts.',
 'flowchart LR\n A[Authenticated checkout] --> B[Hosted provider session]\n B --> C[Return status UI]\n B --> D[Signed webhook]\n D --> E[Receipt and provider verification]\n E --> F[Observed subscription]\n F --> G[Effective entitlement]'),
 ('deletion','Delete an account with recovery','Understand why the cleanup job outlives User.',[
 ('Confirm owner intent','requestAccountDeletion locks the owner and requires the exact account email. The user-facing action authenticates before invoking it.','src/lib/account.ts','export async function requestAccountDeletion'),
 ('Commit unavailability and recovery state','Mark deletionRequestedAt, disable Gmail authorization, increment billing version and create/update the deletion job in the same transaction.','src/lib/account.ts','await ensureDeletionJob'),
 ('Remove the normal credential copy','The job retains a deadline-limited encrypted revocation credential; the User credential is cleared. Cancel only eligible queued work; attempted evidence needs draining.','src/lib/account.ts','// Only the job needs'),
 ('Continue external cleanup','runDeletionJob coordinates billing cancellation, credential revocation, content and storage cleanup with durable markers/leases. Exact ordering and drain deadlines are in the job source.','src/lib/deletion-jobs.ts','export async function runDeletionJob'),
 ('Discover unfinished jobs','The daily sweep expires retained credentials, prepares legacy requests, and emits per-owner deletion events for jobs that are due. The job has no User foreign key so recovery survives content deletion.','src/lib/lifecycle-jobs.ts','export const deletionJobSweep')],
 'Wrong confirmation email is rejected. External billing, storage or revocation failures leave recoverable state rather than pretending cleanup completed. Credential expiry can erase the credential before revocation succeeds; the job records incomplete revocation. Deletion tombstones block immediate Google identity recreation.',
 'flowchart LR\n A[Confirm exact email] --> B[Owner transaction]\n B --> C[Disable account and persist job]\n C --> D[Billing and credential recovery]\n D --> E[Drain and delete content/storage]\n E --> F[Retry unfinished external work]')]
for slug,title,desc,steps,failure,diagram in flows:
 ss=[sec(f'{i+1}. {t}',b,p,n) for i,(t,b,p,*rest) in enumerate(steps) for n in [rest[0] if rest else None]]
 ss[0]['diagram']={'code':diagram,'caption':title+' — conceptual order and durable boundaries; see each numbered source reference.'}
 ss.append(sec('Supported failure cases',failure,steps[-1][2],steps[-1][3] if len(steps[-1])>3 else None))
 page('walkthrough-'+slug,title,desc,'Explain each numbered step, then choose one supported failure and identify what durable evidence survives.',ss,'walkthrough')
(R/'content/chapters.json').write_text(json.dumps(pages,indent=2));print(len(pages),'pages authored')
